using System.Windows; using System.Windows.Controls; using System.Windows.Media; using Microsoft.Win32;
namespace AIEngineerStudio.Views;
public sealed class ProjectDialog : Window
{
    readonly ComboBox existing=new(); readonly TextBox name=new(); readonly TextBox folder=new(); readonly TextBox description=new();
    public string? SelectedProject {get;private set;} public string? NewName {get;private set;} public string? DirectoryPath {get;private set;} public string? Description {get;private set;}
    public ProjectDialog(IEnumerable<string> projects){Title="Открыть или создать проект";Width=540;Height=470;WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=(Brush)Application.Current.Resources["PanelBg"];var root=new StackPanel{Margin=new Thickness(24)};root.Children.Add(new TextBlock{Text="Проекты",FontSize=19,FontWeight=FontWeights.SemiBold,Foreground=(Brush)Application.Current.Resources["Text"]});root.Children.Add(new TextBlock{Text="Выберите существующий проект или создайте новый.",Foreground=(Brush)Application.Current.Resources["Muted"],Margin=new Thickness(0,4,0,14)});var projectList=projects.ToList();existing.ItemsSource=projectList; if(projectList.Count>0) existing.SelectedIndex=0;existing.Margin=new Thickness(0,0,0,8);root.Children.Add(existing);var open=new Button{Content="Открыть выбранный проект"};open.Click+=(s,e)=>{SelectedProject=existing.SelectedItem?.ToString();if(SelectedProject!=null)DialogResult=true;};root.Children.Add(open);root.Children.Add(new Separator{Margin=new Thickness(0,18,0,0)});root.Children.Add(new TextBlock{Text="Новый проект",Foreground=(Brush)Application.Current.Resources["Text"],FontWeight=FontWeights.SemiBold});name.Margin=new Thickness(0,7,0,5);name.Text="Название проекта";root.Children.Add(name);var line=new DockPanel();folder.Text="Рабочая папка";line.Children.Add(folder);var choose=new Button{Content="Обзор",Margin=new Thickness(7,0,0,0)};choose.Click+=(s,e)=>{var d=new OpenFolderDialog();if(d.ShowDialog()==true)folder.Text=d.FolderName;};line.Children.Add(choose);root.Children.Add(line);description.Text="Описание и контекст проекта";description.AcceptsReturn=true;description.Height=65;description.Margin=new Thickness(0,7,0,10);root.Children.Add(description);var create=new Button{Content="Создать проект"};create.Click+=(s,e)=>{if(string.IsNullOrWhiteSpace(name.Text)||string.IsNullOrWhiteSpace(folder.Text)){MessageBox.Show("Укажите имя и рабочую папку.");return;}NewName=name.Text.Trim();DirectoryPath=folder.Text.Trim();Description=description.Text.Trim();DialogResult=true;};root.Children.Add(create);Content=root;}
}
